<?php
require_once __DIR__.'/_data.php';
$db=storefront_db();$customer=$db?marketplace_customer($db):null;if(!$customer)legacy_redirect('masuk?next=bantuan-pesanan');
$cid=(int)$customer['id'];marketplace_service_install($db);
if(is_post()){
    if(!CSRF::verify()){flash('error','Token keamanan tidak valid.');legacy_redirect('bantuan-pesanan');}
    try{
        $orderId=(int)($_POST['order_id']??0);$type=trim((string)($_POST['case_type']??'support'));$reason=trim((string)($_POST['reason']??''));$note=trim((string)($_POST['note']??''));
        if($orderId<=0)throw new RuntimeException('Pilih pesanan terlebih dahulu.');
        if($note===''&&$reason==='')throw new RuntimeException('Jelaskan kebutuhan atau kendala Anda.');
        $case=marketplace_service_create($db,$cid,$orderId,$type,$reason,$note);
        flash('success','Pengajuan bantuan berhasil dibuat.');legacy_redirect('bantuan-pesanan/'.(int)$case['id']);
    }catch(Throwable $e){flash('error',$e->getMessage());legacy_redirect('bantuan-pesanan');}
}
$orders=$db->prepare("SELECT id,order_number,order_status,payment_status,grand_total,created_at FROM online_orders WHERE customer_id=? ORDER BY id DESC LIMIT 100");$orders->execute([$cid]);$orders=$orders->fetchAll()?:[];
$cases=$db->prepare("SELECT c.*,o.order_number FROM marketplace_service_cases c JOIN online_orders o ON o.id=c.order_id WHERE c.customer_id=? ORDER BY c.id DESC");$cases->execute([$cid]);$cases=$cases->fetchAll()?:[];
$pageTitle='Bantuan Pesanan';$activePage='support';require __DIR__.'/_header.php';
?>
<style>.support-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:22px}.support-case{display:flex;align-items:center;gap:14px;padding:15px 0;border-bottom:1px solid #eef2f7;text-decoration:none;color:inherit}.support-case:last-child{border-bottom:0}.support-case .icon{width:44px;height:44px;border-radius:14px;background:#f3e8ff;display:grid;place-items:center}.support-case .body{flex:1}.support-case small{color:#64748b}.support-status{font-size:12px;font-weight:800;padding:5px 9px;border-radius:999px;background:#f1f5f9}.support-form label{display:block;font-weight:800;margin:12px 0 6px}.support-form select,.support-form input,.support-form textarea{width:100%;border:1px solid #dbe3ee;border-radius:12px;padding:12px;background:#fff}.support-form textarea{min-height:120px;resize:vertical}.support-help{padding:12px 14px;background:#fff7ed;border-radius:12px;color:#9a3412;font-size:13px;line-height:1.55}@media(max-width:900px){.support-grid{grid-template-columns:1fr}}</style>
<main class="inner-page account-page"><section class="store-container account-hero"><div><span class="eyebrow">LAYANAN PELANGGAN</span><h1>Bantuan Pesanan</h1><p>Pembatalan, retur, refund, komplain, dan percakapan dengan admin marketplace.</p></div></section><section class="store-container support-grid"><section class="checkout-box"><div class="account-section-head"><div><small>RIWAYAT BANTUAN</small><h2>Pengajuan Saya</h2></div></div><?php if(!$cases):?><div class="account-empty"><i class="bi bi-chat-square-dots"></i><h3>Belum ada pengajuan</h3><p>Buat pengajuan jika ada kendala pada pesanan.</p></div><?php else:?><?php foreach($cases as $c):?><a class="support-case" href="<?=legacy_base_url('bantuan-pesanan/'.(int)$c['id'])?>"><span class="icon"><i class="bi bi-chat-left-text"></i></span><div class="body"><b><?=e($c['case_number'])?> • <?=e($c['order_number'])?></b><div><?=e(marketplace_service_type_label((string)$c['case_type']))?></div><small><?=e(date('d M Y H:i',strtotime((string)$c['created_at'])))?></small></div><span class="support-status"><?=e(marketplace_service_status_label((string)$c['status']))?></span></a><?php endforeach;?><?php endif;?></section><section class="checkout-box"><div class="account-section-head"><div><small>BUAT PENGAJUAN</small><h2>Butuh Bantuan?</h2></div></div><form method="post" class="support-form"><?=CSRF::input()?><label>Pesanan</label><select name="order_id" required><option value="">Pilih pesanan</option><?php foreach($orders as $o):?><option value="<?=(int)$o['id']?>"><?=e($o['order_number'])?> • <?=e(marketplace_order_status_label((string)$o['order_status']))?> • <?=rupiah($o['grand_total'])?></option><?php endforeach;?></select><label>Jenis Pengajuan</label><select name="case_type"><option value="support">Bantuan Pesanan</option><option value="complaint">Komplain Pesanan</option><option value="cancel_refund">Pembatalan & Refund</option><option value="return_refund">Retur & Refund</option></select><label>Alasan</label><input name="reason" maxlength="190" placeholder="Contoh: salah produk / berubah pikiran / barang bermasalah"><label>Detail</label><textarea name="note" placeholder="Jelaskan kebutuhan Anda secara lengkap..."></textarea><div class="support-help">Pembatalan otomatis hanya aman untuk order yang belum dibayar. Untuk order yang sudah dibayar, admin akan meninjau pengajuan dan proses refund dicatat terpisah.</div><button class="btn-primary-store full" style="margin-top:14px"><i class="bi bi-send"></i> Kirim Pengajuan</button></form></section></section></main>
<?php require __DIR__.'/_footer.php';?>
